<?php
function sb_source_section($r){
 $rows=[];$data=$r['balance_report'];if(isset($data['product'])){$p=$data['product'];foreach($data['sources'] as $s)$rows[]=[$p['master_sku'],$p['name'],'NS-'.$s['id'],$s['condition'],$s['received'],$s['quantity'],$s['released'],$s['remaining'],$s['reference']];}else $rows=$data['sources']??[];
 return ['name'=>'Source Records','headers'=>['Master SKU','Product','Source Record','Condition','Received Date','Received Quantity (pcs)','Linked Releases (pcs)','Source Remaining (pcs)','Reference'],'rows'=>$rows];
}
function sb_export_meta($r){$f=$r['filters'];$meta=[($f['report']==='product_master'?'Records':'As Of Date')=>($f['report']==='product_master'?'Current Product Master':$f['as_of']),'Filters'=>report_readable_filters($f),'Generated'=>$r['generated'],'Generated By'=>$r['user'],'Quantity Unit'=>'pcs'];if(isset($r['balance_report']['product'])){$p=$r['balance_report']['product'];$meta['Product']=$p['master_sku'].' · '.$p['name'];}if(isset($r['balance_report']['source_remaining']))$meta['Source Remaining Quantity (unverified for legacy links)']=$r['balance_report']['source_remaining'];return $meta;}
function sb_export_sections($r){
 $sections=[];if($r['summary'])$sections[]=['name'=>'Ending Totals','headers'=>['Metric','Quantity (pcs)'],'rows'=>array_map(fn($k,$v)=>[$k,(int)$v],array_keys($r['summary']),array_values($r['summary']))];
 if($r['filters']['report']==='stock_balance_detail'){$data=$r['balance_report'];$sections[]=['name'=>'Reconciliation','headers'=>['Balance / Movement','Sellable (pcs)','Non-Sellable (pcs)','Physical (pcs)'],'rows'=>overview_matrix_rows($data['rollforward'],['from'=>$data['roll_from'],'to'=>$r['filters']['as_of']])];}
 $names=['stocks'=>'Stock Balance','platforms'=>'Platform Inventory','restricted'=>'Non-Sellable by Product','product_master'=>'Product Master','stock_balance_detail'=>'Movement History'];$sections[]=['name'=>$names[$r['filters']['report']],'headers'=>$r['headers'],'rows'=>report_export_rows($r)];
 if(in_array($r['filters']['report'],['restricted','stock_balance_detail'],true))$sections[]=sb_source_section($r);return $sections;
}
function sb_write_xlsx($path,$r){overview_write_xlsx($path,$r,sb_export_sections($r),sb_export_meta($r));}
function sb_print_document($r){
 echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'.e($r['title']).'</title><style>body{font:12px Arial,sans-serif;color:#16263c;margin:24px}h1{font-size:22px}h2{font-size:17px;margin-top:24px}table{width:100%;border-collapse:collapse;margin:10px 0 20px}th,td{padding:8px;border-bottom:1px solid #cfd8e3;text-align:left;overflow-wrap:anywhere}th{background:#edf2f7}thead{display:table-header-group}tr{break-inside:avoid}.number{text-align:right;font-variant-numeric:tabular-nums}.meta,.notes{line-height:1.7;margin:12px 0}.notes{color:#53647a}@page{size:A4 landscape;margin:12mm}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>'.e($r['title']).'</h1><b>E-commerce Inventory Management System</b><div class="meta">';foreach(sb_export_meta($r) as $key=>$value)echo e($key).': '.e($value).'<br>';echo '</div>';
 foreach(sb_export_sections($r) as $section){[$headers,$rows]=export_current_product_details($section['headers'],$section['rows']);echo '<h2>'.e($section['name']).'</h2><table><thead><tr>';foreach($headers as $header)echo '<th>'.e($header).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $value)echo '<td'.(is_int($value)?' class="number"':'').'>'.e(is_int($value)?number_format($value):$value).'</td>';echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.count($headers).'">No matching records.</td></tr>';echo '</tbody></table>';}
 echo '<div class="notes">';foreach($r['notes'] as $note)echo '<p>'.e($note).'</p>';echo '</div></body></html>';
}
